 static FluidTank tank(FluidType t,int max,int fill,int pressure){FluidTank f=new FluidTank(t,max).withPressure(pressure);f.setFill(fill);return f;}
 static void tanks(){
  FluidTank t=tank(WATER,16000,1000,2);t.withPressure(2);check(t.getFill()==1000,"same pressure retains");t.withPressure(1);check(t.getFill()==0,"changed pressure clears");t.setFill(900);t.setTankType(WATER);check(t.getFill()==900,"same type retains");t.setTankType(null);check(t.getTankType()==Fluids.NONE&&t.getFill()==0,"null type clears to NONE");t.conform(new FluidStack(LAVA,999,3));check(t.getTankType()==LAVA&&t.getPressure()==3&&t.getFill()==0,"conform intentionally ignores stack amount");t.setFill(12000);check(t.changeTankSize(4000)==8000&&t.getFill()==4000,"resize excess");check(t.changeTankSize(5000)==0&&t.getFill()==4000,"resize larger");
  for(int fill:new int[]{-1,0,1,15999,16000,16001,Integer.MAX_VALUE})for(int pressure:new int[]{0,1,32767,32768,-1}) {
   t=tank(WATER,16000,fill,pressure);NBTTagCompound n=new NBTTagCompound();t.writeToNBT(n,"tank");check(n.getInteger("tank")==fill&&n.getInteger("tank_max")==16000&&n.getInteger("tank_type")==WATER.getID()&&n.getShort("tank_p")== (short)pressure,"exact NBT keys/types");FluidTank r=new FluidTank(LAVA,3);r.readFromNBT(n,"tank");check(r.getFill()==Math.max(0,Math.min(fill,16000))&&r.getMaxFill()==16000&&r.getTankType()==WATER&&r.getPressure()==(short)pressure,"NBT original clamp and signed pressure");
   io.netty.buffer.ByteBuf b=io.netty.buffer.Unpooled.buffer();t.serialize(b);check(b.readableBytes()==14,"14 byte layout");r.deserialize(b);check(r.getFill()==fill&&r.getMaxFill()==16000&&r.getTankType()==WATER&&r.getPressure()==(short)pressure&&!b.isReadable(),"wire no new clamp");b.release();
  }
  NBTTagCompound old=new NBTTagCompound();old.setString("tank_type","water");old.setInteger("tank",50);FluidTank r=new FluidTank(LAVA,100);r.readFromNBT(old,"tank");check(r.getTankType()==WATER&&r.getMaxFill()==100&&r.getFill()==0,"missing saved max preserves local capacity but original clamps to zero");old.setInteger("tank_max",-5);r.readFromNBT(old,"tank");check(r.getMaxFill()==100&&r.getFill()==-5,"negative saved max original quirk");r.resetTank();check(r.getTankType()==Fluids.NONE&&r.getFill()==0&&r.getPressure()==0&&r.getMaxFill()==100,"reset retains capacity");
 }
 static void containers(){
  FluidContainerRegistry.clearRegistry();FluidContainerRegistry.registerContainer(new FluidContainer(stack(full,1),stack(empty,1),WATER,1000));FluidContainerRegistry.registerContainer(new FluidContainer(stack(ore,1),null,WATER,125));
  for(ItemStack missing:new ItemStack[]{null,ItemStack.EMPTY,stack(empty,0)}){check(FluidContainerRegistry.getFluidContent(missing,WATER)==0&&FluidContainerRegistry.getFluidType(missing)==Fluids.NONE&&FluidContainerRegistry.getFullContainer(missing,WATER)==null&&FluidContainerRegistry.getEmptyContainer(missing)==null&&FluidContainerRegistry.getContainer(WATER,missing)==null,"null and native EMPTY registry input");FluidTank t=tank(WATER,5000,2000,0);check(!t.loadTank(0,1,new ItemStack[]{missing,ItemStack.EMPTY})&&!t.unloadTank(0,1,new ItemStack[]{missing,ItemStack.EMPTY})&&t.getFill()==2000,"empty tank input no-op");}
  for(int count:new int[]{1,2,16})for(int outCount:new int[]{0,1,63,64})for(boolean loading:new boolean[]{false,true}) {
   FluidTank t=tank(WATER,16000,loading?1000:5000,0);ItemStack input=stack(loading?full:empty,count);input.setStackDisplayName("named");NBTTagCompound extra=new NBTTagCompound();extra.setString("radiation-test","preserve-input-only");input.setTagInfo("custom",extra);ItemStack[] slots={input,outCount==0?ItemStack.EMPTY:stack(loading?empty:full,outCount)};
   boolean result=loading?t.loadTank(0,1,slots):t.unloadTank(0,1,slots);boolean transfer=outCount<64;check(result==transfer,"tank success based on actual delta");check(t.getFill()==(loading?1000:5000)+(transfer?(loading?1000:-1000):0),"container/tank conservation");check(slots[0].getCount()==count-(transfer?1:0),"input debit");check(slots[1].getCount()==outCount+(transfer?1:0),"output receipt");if(transfer)check(slots[1].getDisplayName().equals("named"),"original display name copied");if(slots[0].getCount()>0)check(slots[0].getSubCompound("custom").getString("radiation-test").equals("preserve-input-only"),"remaining input NBT unchanged");check(input.getCount()==count-(transfer?1:0),"original mutable input identity");
  }
  FluidLoaderStandard loader=new FluidLoaderStandard();FluidTank t=tank(WATER,2000,1000,0);ItemStack[] slots={stack(empty,1),ItemStack.EMPTY};check(!loader.fillItem(slots,0,1,t)&&t.getFill()==0&&slots[1].getItem()==full,"original fill handler false even after success");
  t=tank(WATER,2000,0,0);slots=new ItemStack[]{stack(full,1),stack(other,1)};check(loader.emptyItem(slots,0,1,t)&&t.getFill()==0&&slots[0].getCount()==1,"original empty handler true on compatible capacity even blocked output");
  for(ItemStack output:new ItemStack[]{null,ItemStack.EMPTY,stack(other,3)}){t=tank(WATER,2000,0,0);slots=new ItemStack[]{stack(ore,1),output};check(t.loadTank(0,1,slots)&&t.getFill()==125&&slots[0].isEmpty(),"ore with no returned container");check(output==null||output.isEmpty()?slots[1].isEmpty():slots[1]==output&&output.getCount()==3,"no-container output untouched/EMPTY");}
  t=tank(WATER,2000,1500,0);slots=new ItemStack[]{stack(full,2),ItemStack.EMPTY};check(!t.loadTank(0,1,slots)&&slots[0].getCount()==2&&t.getFill()==1500,"capacity prevents partial canister consumption");t.withPressure(1);check(!t.loadTank(0,1,slots),"pressurized normal input blocked");
  ItemStack a=FluidContainerRegistry.getFullContainer(stack(empty,20),WATER),b=FluidContainerRegistry.getFullContainer(stack(empty,1),WATER);a.setCount(9);check(b.getCount()==1&&FluidContainerRegistry.getFluidType(stack(full,20))==WATER&&FluidContainerRegistry.getFluidContent(stack(full,20),WATER)==1000,"registry copy and per-container amount independent of stack count");
 }
 static class Identifier extends Item implements IItemFluidIdentifier {public FluidType getType(World w,int x,int y,int z,ItemStack s){check(w==null&&x==0&&y==0&&z==0,"identifier original null-world contract");return LAVA;}}
 static void emptyContainerRegistration(){Item nativeOre=item("native_empty_container");FluidContainerRegistry.registerContainer(new FluidContainer(stack(nativeOre,1),ItemStack.EMPTY,WATER,125));check(FluidContainerRegistry.getEmptyContainer(stack(nativeOre,1))==null,"native EMPTY container normalized to original null API contract");FluidTank t=tank(WATER,1000,0,0);ItemStack[] slots={stack(nativeOre,1),ItemStack.EMPTY};slots[0].setStackDisplayName("do-not-name-shared-empty");check(t.loadTank(0,1,slots)&&t.getFill()==125&&slots[0].isEmpty()&&slots[1].isEmpty()&&!ItemStack.EMPTY.hasDisplayName(),"EMPTY no-container registration does not mutate shared sentinel");}
 static void identifier(){Item id=new Identifier();net.minecraftforge.fml.common.registry.ForgeRegistries.ITEMS.register(id.setRegistryName("test","id"));FluidTank t=tank(WATER,1000,500,0);ItemStack input=stack(id,3);input.setStackDisplayName("id-name");ItemStack[] slots={input,ItemStack.EMPTY};check(t.setType(0,1,slots)&&t.getTankType()==LAVA&&t.getFill()==0&&slots[0].isEmpty()&&slots[1].getCount()==3&&slots[1]!=input&&slots[1].getDisplayName().equals("id-name"),"identifier copies whole original stack, not one");t.setFill(100);check(!t.setType(1,slots)&&t.getFill()==100,"unchanged identifier no drain");t.setTankType(WATER);slots=new ItemStack[]{stack(id,1),stack(other,1)};check(!t.setType(0,1,slots),"occupied output blocks identifier");}
 static class Fillable extends Item implements IFillableItem {
  boolean accepts=true,provides=true;int held,cap=1000;public boolean acceptsFluid(FluidType t,ItemStack s){return accepts;}public int tryFill(FluidType t,int n,ItemStack s){int a=Math.min(n,cap-held);held+=a;return n-a;}public boolean providesFluid(FluidType t,ItemStack s){return provides;}public int tryEmpty(FluidType t,int n,ItemStack s){int a=Math.min(n,held);held-=a;return a;}public FluidType getFirstFluidType(ItemStack s){return WATER;}public int getFill(ItemStack s){return held;}
 }
 static void loaders() throws Exception {
  Fillable i=new Fillable();net.minecraftforge.fml.common.registry.ForgeRegistries.ITEMS.register(i.setRegistryName("test","fillable"));ItemStack s=stack(i,1);FluidLoaderFillableItem l=new FluidLoaderFillableItem();FluidTank t=tank(WATER,2000,1500,0);check(l.fill(s,t)&&i.held==1000&&t.getFill()==500,"fillable accepts remainder accounting");t.setFill(0);check(!l.empty(s,t)&&t.getFill()==1000&&i.held==0,"fillable empty returns tank-full condition");i.accepts=false;t.setFill(500);check(l.fill(s,t)&&t.getFill()==500,"rejected fillable returns true original");i.held=700;t.setFill(1600);check(l.empty(s,t)&&t.getFill()==2000&&i.held==300,"fillable capacity and remainder");t.withPressure(1);check(!l.fill(s,t),"fillable pressurized fill refused");
  ItemStack armor=new ItemStack(net.minecraft.init.Items.IRON_CHESTPLATE);ArmorModHandler.mods=new ItemStack[]{null,ItemStack.EMPTY,s};ArmorModHandler.applied=0;i.accepts=true;i.held=0;t.withPressure(0);t.setFill(800);check(!l.fill(armor,t)&&i.held==800&&t.getFill()==0&&ArmorModHandler.applied==1,"armor fill recursive apply and outer false");check(!l.empty(armor,t)&&i.held==0&&t.getFill()==800&&ArmorModHandler.applied==1,"original armor empty does not apply mod");ArmorModHandler.mods=new ItemStack[0];
  ItemInfiniteFluid infinite=new ItemInfiniteFluid(WATER,300);net.minecraftforge.fml.common.registry.ForgeRegistries.ITEMS.register(infinite.setRegistryName("test","infinite"));FluidLoaderInfinite inf=new FluidLoaderInfinite();ItemStack[] slots={stack(infinite,1),ItemStack.EMPTY};t=tank(WATER,1000,900,0);check(inf.emptyItem(slots,0,1,t)&&t.getFill()==1000,"infinite clamps addition");check(inf.fillItem(slots,0,1,t)&&t.getFill()==700,"infinite drain");infinite.allowed=false;t.withPressure(2);check(!inf.fillItem(slots,0,1,t)&&inf.emptyItem(slots,0,1,t)&&t.getFill()==300,"original infinite empty omits allowPressure check");infinite.operate=false;check(!inf.emptyItem(slots,0,1,t),"environment gate");infinite.operate=true;t.setTankType(LAVA);check(!inf.emptyItem(slots,0,1,t),"type gate");infinite.allowed=true;infinite.type=WATER;infinite.chance=3;t=tank(WATER,10000,0,0);java.lang.reflect.Field rf=FluidLoaderInfinite.class.getDeclaredField("rand");rf.setAccessible(true);rf.set(null,new Random(814));Random oracle=new Random(814);int expected=0;for(int n=0;n<20;n++){if(oracle.nextInt(3)==0)expected=Math.min(expected+300,10000);check(inf.emptyItem(slots,0,1,t)&&t.getFill()==expected,"original seeded chance and RNG consumption");}infinite.chance=1;infinite.type=null;t.setTankType(Fluids.NONE);check(!inf.emptyItem(slots,0,1,t),"NONE infinite fill forbidden");
 }
 static long oracle(int[] fills,int[] caps,boolean[] match,long amount,boolean send){int count=0;for(boolean m:match)if(m)count++;if(count>1){int first=(int)Math.floor((double)amount/count);for(int n=0;n<fills.length;n++)if(match[n]){int v=Math.min(first,send?fills[n]:caps[n]-fills[n]);fills[n]+=send?-v:v;amount-=v;}}if(amount>0)for(int n=0;n<fills.length;n++)if(match[n]){int v=(int)Math.min(amount,send?fills[n]:caps[n]-fills[n]);fills[n]+=send?-v:v;amount-=v;}return amount;}
 static void transfers(){
  Endpoint ranges=new Endpoint(new FluidTank[]{tank(WATER,10,1,2),tank(WATER,10,2,4),tank(LAVA,10,3,1)},new FluidTank[]{tank(WATER,10,1,2),tank(WATER,10,2,4)});check(java.util.Arrays.equals(ranges.getReceivingPressureRange(WATER),new int[]{2,4})&&java.util.Arrays.equals(ranges.getProvidingPressureRange(WATER),new int[]{2,4}),"pressure range filtering");check(java.util.Arrays.equals(ranges.getReceivingPressureRange(Fluids.NONE),new int[]{0,0}),"missing pressure range original shared default");

  for(long amount:new long[]{-1,0,1,2,99,1000,3000,Integer.MAX_VALUE,(long)Integer.MAX_VALUE+1,Long.MAX_VALUE})for(int pressure:new int[]{0,1,2})for(int mask=0;mask<8;mask++) {
   FluidTank[] ts={tank((mask&1)==0?WATER:LAVA,1000,300,0),tank((mask&2)==0?WATER:LAVA,500,500,1),tank((mask&4)==0?WATER:LAVA,2000,1900,0)};int[] expected={300,500,1900},caps={1000,500,2000};boolean[] match=new boolean[3];long demand=0,available=0;for(int n=0;n<3;n++){match[n]=ts[n].getTankType()==WATER&&ts[n].getPressure()==pressure;if(match[n]){demand+=caps[n]-expected[n];available+=expected[n];}}
   Endpoint e=new Endpoint(ts,ts);check(e.getDemand(WATER,pressure)==demand&&e.getFluidAvailable(WATER,pressure)==available,"pressure and type selection");long remainder=oracle(expected,caps,match,amount,false);check(e.transferFluid(WATER,pressure,amount)==remainder,"original two-pass remainder including overflow casts");for(int n=0;n<3;n++)check(ts[n].getFill()==expected[n],"receiver two-pass exact order");oracle(expected,caps,match,amount,true);e.useUpFluid(WATER,pressure,amount);for(int n=0;n<3;n++)check(ts[n].getFill()==expected[n],"sender two-pass exact order");
  }
  W world=new W();Endpoint source=new Endpoint(new FluidTank[0],new FluidTank[]{tank(WATER,1000,900,0)}),sink=new Endpoint(new FluidTank[]{tank(WATER,600,100,0)},new FluidTank[0]);source.setWorld(world);source.setPos(new BlockPos(-3,64,11));sink.setWorld(world);sink.setPos(new BlockPos(-2,64,11));world.tiles.put(sink.getPos(),sink);world.tiles.put(source.getPos(),source);source.providerSpeed=300;sink.receiverSpeed=200;api.hbm.tile.ILoadedTile.TileAccessCache.cache.clear();UniNodespace.node=null;source.tryProvide(WATER,0,world,-2,64,11,ForgeDirection.EAST);check(source.sending[0].getFill()==700&&sink.receiving[0].getFill()==300,"direct native tile lookup applies both speed caps and source debit");source.tryProvide(WATER,1,world,-2,64,11,ForgeDirection.EAST);check(source.sending[0].getFill()==700&&sink.receiving[0].getFill()==300,"wrong pressure no transfer");source.tryProvide(WATER,0,world,-3,64,11,ForgeDirection.EAST);check(source.sending[0].getFill()==700,"self/no tile excluded");
  Endpoint replacement=new Endpoint(new FluidTank[]{tank(WATER,1000,0,0)},new FluidTank[0]);sink.invalidate();world.tiles.put(sink.getPos(),replacement);source.tryProvide(WATER,0,world,-2,64,11,ForgeDirection.EAST);check(replacement.receiving[0].getFill()==300&&source.sending[0].getFill()==400,"actual loaded-tile cache invalidation refresh");
  GenNode<FluidNetMK2> node=new GenNode<>(null);node.net=new FluidNetMK2();UniNodespace.node=node;UniNodespace.queries.clear();for(ForgeDirection d:ForgeDirection.VALID_DIRECTIONS){BlockPos p=source.getPos().add(d.offsetX,d.offsetY,d.offsetZ);world.tiles.put(p,new Endpoint(new FluidTank[0],new FluidTank[0]));}api.hbm.tile.ILoadedTile.TileAccessCache.cache.clear();source.subscribeToAllAround(WATER,source);check(node.net.receivers.size()==6&&UniNodespace.queries.size()==6,"six native neighbor subscriptions");for(int n=0;n<6;n++){ForgeDirection d=ForgeDirection.VALID_DIRECTIONS[n];check(UniNodespace.queries.get(n).equals((-3+d.offsetX)+","+(64+d.offsetY)+","+(11+d.offsetZ)),"original neighbor ordering and axis");}source.unsubscribeToAllAround(WATER,source);check(node.net.receivers.isEmpty(),"six unsubscribe removals");source.sendFluidToAll(source.sending[0],source);check(node.net.providers.size()==6,"six provider subscriptions");FluidNode created=source.createNode(WATER);check(created.positions[0].getX()==-3&&created.positions[0].getY()==64&&created.positions[0].getZ()==11&&created.connections.length==6,"native tile node position");check(created.connections[0].getX()==-2&&created.connections[1].getX()==-4&&created.connections[2].getY()==65&&created.connections[3].getY()==63&&created.connections[4].getZ()==12&&created.connections[5].getZ()==10,"node original +X -X +Y -Y +Z -Z order");
 }
